(function () {
  const KEY = 'vanaveda-cart-v1';
  const products = () => window.VANAVEDA_PRODUCTS || [];
  const get = () => { try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (_) { return []; } };
  const save = items => { localStorage.setItem(KEY, JSON.stringify(items)); updateUI(); window.dispatchEvent(new CustomEvent('vanaveda:cart')); };
  const findProduct = id => products().find(p => p.id === id);
  function add(id, size, quantity) { const item=findProduct(id);if(!item)return;const selected=size||item.sizes[0];const qty=Math.max(1,Number(quantity)||1);const cart=get();const found=cart.find(row=>row.id===id&&row.size===selected);if(found)found.quantity+=qty;else cart.push({id,size:selected,quantity:qty});save(cart);openDrawer();toast(`${item.name} added to your bag`); }
  function remove(id,size){save(get().filter(row=>!(row.id===id&&row.size===size)));renderCartPage();renderDrawer();}
  function setQuantity(id,size,quantity){const cart=get();const row=cart.find(item=>item.id===id&&item.size===size);if(!row)return;row.quantity=Math.max(0,Number(quantity)||0);save(cart.filter(item=>item.quantity>0));renderCartPage();renderDrawer();}
  function detailed(){return get().map(row=>({...row,product:findProduct(row.id)})).filter(row=>row.product);}
  function totals(){return detailed().reduce((acc,row)=>({count:acc.count+row.quantity,subtotal:acc.subtotal+row.product.price*row.quantity}),{count:0,subtotal:0});}
  function updateUI(){const {count}=totals();document.querySelectorAll('[data-cart-count]').forEach(el=>{el.textContent=count;el.hidden=count===0;});}
  function line(row){return `<article class="mini-line"><a href="product-details.html?id=${row.product.id}"><img src="../assets/images/${row.product.image}" alt=""></a><div><a class="mini-line__name" href="product-details.html?id=${row.product.id}">${row.product.name}</a><small>${row.size}</small><div class="quantity" aria-label="Quantity"><button data-cart-dec="${row.product.id}" data-size="${row.size}" aria-label="Decrease quantity">−</button><span>${row.quantity}</span><button data-cart-inc="${row.product.id}" data-size="${row.size}" aria-label="Increase quantity">+</button></div></div><strong>${VANAVEDA_FORMAT_PRICE(row.product.price*row.quantity)}</strong><button class="text-button mini-remove" data-cart-remove="${row.product.id}" data-size="${row.size}">Remove</button></article>`;}
  function renderDrawer(){const target=document.querySelector('[data-mini-cart-items]');if(!target)return;const rows=detailed();target.innerHTML=rows.length?rows.map(line).join(''):`<div class="empty-state compact"><span>☙</span><h3>Your bag is ready for a ritual.</h3><p>Add something thoughtful from the shop.</p><a class="button button--small" href="products.html">Browse products</a></div>`;const footer=document.querySelector('[data-mini-cart-footer]');if(footer){footer.hidden=!rows.length;footer.querySelector('[data-mini-subtotal]').textContent=VANAVEDA_FORMAT_PRICE(totals().subtotal);}}
  function openDrawer(){renderDrawer();document.querySelector('[data-cart-drawer]')?.classList.add('is-open');document.querySelector('[data-cart-backdrop]')?.classList.add('is-open');document.body.classList.add('no-scroll');}
  function closeDrawer(){document.querySelector('[data-cart-drawer]')?.classList.remove('is-open');document.querySelector('[data-cart-backdrop]')?.classList.remove('is-open');document.body.classList.remove('no-scroll');}
  function renderCartPage(){const target=document.querySelector('[data-cart-page]');if(!target)return;const rows=detailed();if(!rows.length){target.innerHTML=`<div class="empty-state"><span>☙</span><h2>Your bag is empty</h2><p>Explore botanical teas, oils, skincare and everyday ritual tools.</p><a class="button" href="products.html">Start shopping</a></div>`;return;}const {subtotal}=totals();target.innerHTML=`<div class="cart-layout"><div class="cart-lines">${rows.map(line).join('')}</div><aside class="order-summary"><p class="eyebrow">Order summary</p><div><span>Subtotal</span><strong>${VANAVEDA_FORMAT_PRICE(subtotal)}</strong></div><p>Shipping and taxes are calculated when a verified checkout service is connected.</p><button class="button button--full" data-checkout-request>Request checkout link</button><a href="products.html" class="text-link">Continue shopping</a><p class="form-status" data-checkout-status aria-live="polite"></p></aside></div>`;}
  function toast(message){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';el.setAttribute('role','status');document.body.appendChild(el);}el.textContent=message;el.classList.add('is-visible');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('is-visible'),2600);}
  document.addEventListener('click',event=>{const addBtn=event.target.closest('[data-add-to-cart]');if(addBtn)add(addBtn.dataset.addToCart,addBtn.dataset.size,addBtn.dataset.quantity);const removeBtn=event.target.closest('[data-cart-remove]');if(removeBtn)remove(removeBtn.dataset.cartRemove,removeBtn.dataset.size);const inc=event.target.closest('[data-cart-inc]');if(inc){const row=get().find(x=>x.id===inc.dataset.cartInc&&x.size===inc.dataset.size);if(row)setQuantity(row.id,row.size,row.quantity+1);}const dec=event.target.closest('[data-cart-dec]');if(dec){const row=get().find(x=>x.id===dec.dataset.cartDec&&x.size===dec.dataset.size);if(row)setQuantity(row.id,row.size,row.quantity-1);}if(event.target.closest('[data-open-cart]'))openDrawer();if(event.target.closest('[data-close-cart]')||event.target.matches('[data-cart-backdrop]'))closeDrawer();if(event.target.closest('[data-checkout-request]')){event.target.closest('[data-checkout-request]').disabled=true;document.querySelector('[data-checkout-status]').textContent='Checkout is not yet connected. Your bag is saved on this device; please contact the care team to continue.';}});
  document.addEventListener('DOMContentLoaded',()=>{updateUI();renderCartPage();});
  window.VanaVedaCart={get,add,remove,setQuantity,totals,renderCartPage,openDrawer};
})();
